-- Rifts World Book 24: China 1 - its bestiary and its notable NPCs.
-- 2 creatures (migration 074) and 23 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~063-china-1-npcs-and-terra-cotta.sql
--
-- Written by scripts/bestiary-sql.mjs from 3 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.




-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 2 creatures are in' AS assertion, count(*) AS got, 2 AS want
  FROM creatures WHERE slug IN ('terra-cotta-warrior', 'tiny-terra-cotta-warrior');
SELECT 'and 0 of them are playable' AS assertion, count(*) AS got, 0 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('terra-cotta-warrior', 'tiny-terra-cotta-warrior');
SELECT 'all 23 notable NPCs are in' AS assertion, count(*) AS got, 23 AS want
  FROM notable_npcs WHERE slug IN ('huan-shih', 'wu-je-nao', 'chu-chiang', 'xian-ya', 'qin-kuai', 'living-statue-of-qin-kuai', 'lady-wang', 'living-statue-of-lady-wang', 'feng-xiao', 'living-statue-of-feng-xiao', 'feng-zhong', 'living-statue-of-feng-zhong', 'wu-kuan', 'yen-lo', 'pien-cheng', 'tai-shan-chun', 'chi-chou-lu', 'ast-oth', 'zhua-zhao', 'ping-teng', 'tu-shis', 'meng-po-niang-niang', 'huang-di');
SELECT 'the creatures carry 11 attacks' AS assertion, count(*) AS got, 11 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('terra-cotta-warrior', 'tiny-terra-cotta-warrior');
SELECT 'and the notables 25' AS assertion, count(*) AS got, 25 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('huan-shih', 'wu-je-nao', 'chu-chiang', 'xian-ya', 'qin-kuai', 'living-statue-of-qin-kuai', 'lady-wang', 'living-statue-of-lady-wang', 'feng-xiao', 'living-statue-of-feng-xiao', 'feng-zhong', 'living-statue-of-feng-zhong', 'wu-kuan', 'yen-lo', 'pien-cheng', 'tai-shan-chun', 'chi-chou-lu', 'ast-oth', 'zhua-zhao', 'ping-teng', 'tu-shis', 'meng-po-niang-niang', 'huang-di');

